import { addProviderLedgerEntry, assignBookingToProvider, confirmBookingCompletion, createBookingFromDraft, dataModeLabel, getAdminOverview, getAdminProviderApplications, getAuthState, getMyRole, getMyBookings, getProviderLedger, getProviderWorkQueue, isSupabaseConfigured, onAuthStateChange, reviewProviderVerification, signInAccount, signInWithGoogle, signOutAccount, signUpAccount, startPayment, submitProviderVerification, ensureProviderProfile, type AuthState } from './lib/supabase'
import type { BookingDraft, Role } from './types'

const initialDraft: BookingDraft = { issue: '', urgency: 'normal', city: '', district: '', address: '', accessNotes: '', locationSource: 'none', scheduledDate: '', scheduledSlot: '' }

function App() {
  const [theme, setTheme] = useState<'light' | 'dark'>(() => { try { return (localStorage.getItem('homefix-theme') as 'light' | 'dark' | null) ?? 'dark' } catch { return 'dark' } })
  useEffect(() => { document.documentElement.dataset.theme = theme; try { localStorage.setItem('homefix-theme', theme) } catch { /* التخزين قد يكون معطلًا في التصفح الخاص */ } }, [theme])
  return <Shell theme={theme} onThemeChange={() => setTheme((value) => value === 'light' ? 'dark' : 'light')}><Routes><Route path="/" element={<HomePage />} /><Route path="/services" element={<ServicesPage />} /><Route path="/book" element={<BookingPage />} /><Route path="/customer" element={<ProtectedRoute requiredRole="customer"><CustomerPage /></ProtectedRoute>} /><Route path="/provider" element={<ProtectedRoute requiredRole="provider"><ProviderPage /></ProtectedRoute>} /><Route path="/admin" element={<ProtectedRoute requiredRole="admin"><AdminPage /></ProtectedRoute>} /><Route path="/login" element={<LoginPage />} /><Route path="*" element={<Navigate to="/" replace />} /></Routes></Shell>
}

function ProtectedRoute({ children, requiredRole }: { children: React.ReactNode; requiredRole?: Extract<Role, 'customer' | 'provider' | 'admin'> }) {
  const [state, setState] = useState<(AuthState & { role?: Role | null }) | null>(null)
  useEffect(() => { let active = true; Promise.all([getAuthState(), getMyRole()]).then(([auth, role]) => { if (active) setState({ ...auth, role }) }).catch(() => { if (active) setState({ session: null, user: null, role: null }) }); const subscription = onAuthStateChange((next) => { if (active) getMyRole().then((role) => setState({ ...next, role })).catch(() => setState({ ...next, role: null })) }); return () => { active = false; subscription.unsubscribe() } }, [])
  if (!state) return <div className="container loading-state">جارٍ التحقق من جلسة الحساب...</div>
  if (!state.user) return <Navigate to={requiredRole === 'provider' ? '/login?role=provider' : requiredRole === 'customer' ? '/login?role=customer' : '/login'} replace />
  const hasRole = requiredRole === undefined || (requiredRole === 'admin' ? state.role === 'admin' || state.role === 'sub_admin' : state.role === requiredRole)
  if (!hasRole) return <Navigate to={state.role === 'provider' ? '/provider' : state.role === 'admin' || state.role === 'sub_admin' ? '/admin' : state.role === 'customer' ? '/customer' : '/login?error=role-missing'} replace />
  return <>{children}</>
}

function StatusPill({ children, tone = 'neutral' }: { children: React.ReactNode; tone?: 'neutral' | 'success' | 'warning' | 'dark' }) { return <span className={`status-pill ${tone}`}>{children}</span> }
function SectionTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="section-title"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2>{description && <p className="muted section-description">{description}</p>}</div>{action}</div> }
function EmptyState({ icon: Icon = Layers3, title, body, action }: { icon?: LucideIcon; title: string; body: string; action?: React.ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Icon size={22} /></span><h3>{title}</h3><p>{body}</p>{action}</div> }
function DataModeBanner() { return <div className="data-mode-banner"><span className="live-dot" />{dataModeLabel}<span className="banner-separator" />{isSupabaseConfigured ? 'البيانات الحقيقية تظهر حسب صلاحيات الحساب وRLS.' : 'الكتالوج الأساسي متاح، والطلبات الحقيقية تحتاج إعداد متغيرات البيئة.'}<Link to="/customer">اعرف المزيد</Link></div> }

function RequestAuthDialog({ open, onClose, role = 'customer' }: { open: boolean; onClose: () => void; role?: 'customer' | 'provider' }) {
  const [googleError, setGoogleError] = useState('')
  if (!open) return null
  const goGoogle = async () => { setGoogleError(''); try { await signInWithGoogle(role) } catch (error) { setGoogleError(error instanceof Error ? error.message : 'تعذر بدء الدخول عبر Google') } }
  return <div className="royal-modal-backdrop" role="dialog" aria-modal="true"><div className="royal-modal"><button className="modal-close" onClick={onClose} aria-label="إغلاق"><X size={18} /></button><span className="royal-seal">✦</span><span className="eyebrow">خطوة آمنة قبل الطلب</span><h2>ابدأ طلبك بحسابك</h2><p>أنشئ حساب طالب خدمة أو سجّل الدخول لمتابعة الطلب والدفع بعد إكمال العمل.</p>{googleError && <div className="inline-error"><X size={16} />{googleError}</div>}<button className="button google-button button-wide" onClick={goGoogle}><span className="google-g">G</span>المتابعة بحساب Google</button><Link className="button button-primary button-wide" to={`/login?role=${role}`} onClick={onClose}>تسجيل الدخول أو إنشاء حساب <ArrowLeft size={16} /></Link><button className="modal-secondary" onClick={onClose}>سأعود لاحقًا</button></div></div>
}

